CREATE OR REPLACE FUNCTION calculate_disf(air_temp_c NUMERIC, atmos_transparency NUMERIC, humidity_rate NUMERIC, lunar_dist_deg NUMERIC)
RETURNS NUMERIC AS
$$
BEGIN
    RETURN (
        (10 - ABS(air_temp_c - 15) / 10)
        * atmos_transparency
        * (1 - humidity_rate / 200)
        * ((100 - lunar_dist_deg) / 100)
    );
END;
$$ LANGUAGE plpgsql;

